1	/** One executable spec contract for the library, packaged CLI, and merge gate. */
2	export const SPEC_HEADINGS = Object.freeze([
3	  "## Scope", "## What I own", "## What I need from other roles",
4	  "## Decisions made", "## Still unclear",
5	]);
6	
7	export function specPath(roleSlug) {
8	  return `grill/${roleSlug}-spec.md`;
9	}
10	
11	/** Exact H2 lines outside backtick/tilde fences; trailing whitespace is harmless. */
12	export function validateSpec(markdown) {
13	  const sections = new Map(SPEC_HEADINGS.map((heading) => [heading, []]));
14	  const found = [];
15	  const errors = [];
16	  let current = null;
17	  let fence = null;
18	  let inComment = false;
19	  const lines = markdown.replace(/\r\n?/g, "\n").split("\n");
20	  for (const [index, original] of lines.entries()) {
21	    if (fence) {
22	      if (new RegExp(`^ {0,3}${fence.marker}{${fence.length},}[ \\t]*$`).test(original)) {
23	        fence = null;
24	      } else if (current) sections.get(current).push(original);
25	      continue;
26	    }
27	    const opening = !inComment && original.match(/^ {0,3}(`{3,}|~{3,})(.*)$/);
28	    if (opening && !(opening[1][0] === "`" && opening[2].includes("`"))) {
29	      fence = { marker: opening[1][0], length: opening[1].length };
30	      continue;
31	    }
32	    // Comments outside code cannot manufacture headings or nonempty content.
33	    // Inside fences every character, including an unclosed '<!--', is literal.
34	    let line = "";
35	    let cursor = 0;
36	    while (cursor < original.length) {
37	      const boundary = original.indexOf(inComment ? "-->" : "<!--", cursor);
38	      if (boundary === -1) {
39	        line += inComment ? " ".repeat(original.length - cursor) : original.slice(cursor);
40	        break;
41	      }
42	      if (inComment) {
43	        line += " ".repeat(boundary + 3 - cursor);
44	        cursor = boundary + 3;
45	      } else {
46	        line += original.slice(cursor, boundary) + "    ";
47	        cursor = boundary + 4;
48	      }
49	      inComment = !inComment;
50	    }
51	    const heading = line.replace(/^ {0,3}/, "").trimEnd();
52	    if (/^##(?:[ \t]|$)/.test(heading)) {
53	      current = null;
54	      if (!sections.has(heading) || original.replace(/^ {0,3}/, "").trimEnd() !== heading) {
55	        errors.push(`line ${index + 1}: unexpected or suffixed heading ${heading}`);
56	        continue;
57	      }
58	      if (found.includes(heading)) errors.push(`line ${index + 1}: duplicate heading ${heading}`);
59	      found.push(heading);
60	      current = heading;
61	    } else if (current) {
62	      sections.get(current).push(line);
63	    }
64	  }
65	  const missing = SPEC_HEADINGS.filter((heading) => !found.includes(heading));
66	  if (missing.length) errors.push(`missing headings: ${missing.join(", ")}`);
67	  const unique = [...new Set(found)];
68	  const ordered = SPEC_HEADINGS.filter((heading) => found.includes(heading));
69	  if (unique.some((heading, index) => heading !== ordered[index])) errors.push("headings are out of order");
70	  const content = SPEC_HEADINGS.map((heading) => sections.get(heading).join("\n")
71	    .replace(/^[ \t]*[-*+>][ \t]*$/gm, "").trim());
72	  if (content.every((text) => text.length === 0)) errors.push("spec is wholly empty under its headings");
73	  const thin = SPEC_HEADINGS.filter((_, index) => content[index].length < 12);
74	  return { ok: errors.length === 0, missing, thin, errors };
75	}
